package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class DistributiveArithmeticTest {
 @Test public void preferMeaningfulFactorsWithoutRemovingZeroOrOne(){Generator gen=new Generator(new Random(266));for(String id:List.of(DistributiveArithmetic.ADD,DistributiveArithmetic.SUB)){int meaningful=0,zero=0,one=0;List<String>history=new ArrayList<>();for(int i=0;i<200;i++){Question q=gen.next(id,history,false,CurriculumLimits.NONE);history.add(q.signature());int a=DistributiveArithmetic.read(q).factor();if(a==0)zero++;else if(a==1)one++;else meaningful++;}assertTrue(meaningful>140);assertTrue(zero>0);assertTrue(one>0);}}
 @Test public void bothOperationsAndFactorPositionsRequireBothProductsIndependentOfKeys(){Checker checker=new Checker();for(String id:List.of(DistributiveArithmetic.ADD,DistributiveArithmetic.SUB))for(int direction=0;direction<2;direction++)for(int[]v:List.of(new int[]{3,10,5},new int[]{0,500000,500000},new int[]{1000000,1,0},new int[]{1,1000000,0},new int[]{2,500000,500000})){long p1=(long)v[0]*v[1],p2=(long)v[0]*v[2],inner=id.equals(DistributiveArithmetic.ADD)?(long)v[1]+v[2]:(long)v[1]-v[2],total=v[0]*inner;if(inner<0||inner>1000000||total>1000000)continue;Question q=DistributiveArithmetic.make(id,v[0],v[1],v[2],direction);List<String>answer=Arrays.asList(q.answers.clone());q.answers=new String[]{"poison"};q.expression="poison";assertTrue(checker.check(q,List.of(),answer).correct());for(int i=0;i<7;i++){List<String>wrong=new ArrayList<>(answer);wrong.set(i,""+(Long.parseLong(wrong.get(i))+1));assertEquals(i,checker.check(q,List.of(),wrong).index);}assertEquals(Checker.Status.INPUT_NEEDED,checker.check(q,List.of(),List.of()).status);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(8,h.size());for(int i=0;i<4;i++)assertTrue(h.step(i).accepts(answer.get(i)));assertTrue(h.step(4).accepts(""+inner));assertTrue(h.step(5).accepts(""+p1));assertTrue(h.step(6).accepts(""+p2));assertTrue(h.step(7).accepts(""+total));assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}try{DistributiveArithmetic.make(DistributiveArithmetic.SUB,0,0,1000000,0);fail("Negative inner with zero factor must not bypass domain");}catch(IllegalArgumentException expected){}try{DistributiveArithmetic.make(DistributiveArithmetic.SUB,1000000,2,2,0);fail("Zero final must not bypass products bound");}catch(IllegalArgumentException expected){}}
 @Test public void completeSmallDomainsFreshBeforeOldestIncludingZeroAndBothPositions(){CurriculumLimits l=new CurriculumLimits("minGiven=0;maxGiven=3;maxResult=3;nonnegative=true");for(String id:List.of(DistributiveArithmetic.ADD,DistributiveArithmetic.SUB)){Set<String>all=new HashSet<>();for(int a=0;a<=3;a++)for(int b=0;b<=3;b++)for(int c=0;c<=3;c++){int inner=id.equals(DistributiveArithmetic.ADD)?b+c:b-c;if(inner<0||inner>3||a*b>3||a*c>3||a*inner>3)continue;for(int d=0;d<2;d++)all.add(DistributiveArithmetic.make(id,a,b,c,d).signature());}Generator gen=new Generator(new Random(266));List<String>history=new ArrayList<>();for(int i=0;i<all.size();i++){Question q=gen.next(id,history,false,l);assertTrue(all.contains(q.signature()));assertFalse(history.contains(q.signature()));history.add(q.signature());}assertEquals(all.size(),history.size());assertEquals(history.get(0),gen.next(id,history,false,l).signature());}}
 @Test public void normalGradeSixFreshLargeNumbersBothPositions(){String pack="na-nied-primary-2024-v1";Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,pack);Generator gen=new Generator(new Random(266));for(String id:List.of(DistributiveArithmetic.ADD,DistributiveArithmetic.SUB)){assertTrue(GlobalCurriculum.pack(p).inGrade(id,6));assertFalse(Curriculum.inCurriculum(Catalog.get(id),2022));List<String>history=new ArrayList<>();Set<Integer>directions=new HashSet<>();boolean large=false,nonzero=false;for(int i=0;i<150;i++){Question q=gen.next(id,history,false,GlobalCurriculum.limits(pack,id,6));assertFalse(history.contains(q.signature()));history.add(q.signature());DistributiveArithmetic.Givens g=DistributiveArithmetic.read(q);assertNotNull(g);directions.add(g.direction());large|=Math.max(g.factor(),Math.max(g.first(),g.second()))>=100000;nonzero|=g.total()>0;}assertEquals(2,directions.size());assertTrue(large);assertTrue(nonzero);}}
}
